contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        uint selfBefore = address(this).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted ? (address(this).balance == selfBefore && address(c).balance == balBefore && c.owner() == ownerBefore && c.depositsCount() == depositsBefore) : (address(this).balance == selfBefore + balBefore && address(c).balance == 0 && c.owner() == ownerBefore && c.depositsCount() == depositsBefore));
    }

    receive() external payable {}
}

